import csv
import io
import re


def parse_csv(raw_csv: str):
    reader = csv.reader(io.StringIO(raw_csv, newline=""), delimiter=",", quotechar='"', strict=False)
    parsed = []
    try:
        for row in reader:
            parsed.append([value.lstrip("\ufeff") if index == 0 else value for index, value in enumerate(row)])
    except csv.Error:
        pass

    if not parsed:
        return {"columns": [], "rows": []}

    def nonempty(row):
        return [value for value in row if value.strip()]

    def is_number(value):
        value = value.strip()
        return bool(value) and bool(re.fullmatch(
            r"[+-]?(?:(?:\d+(?:\.\d*)?)|(?:\.\d+))(?:[eE][+-]?\d+)?%?",
            value
        ))

    def repeated_nonempty(values):
        seen = set()
        for value in values:
            if value and value in seen:
                return True
            if value:
                seen.add(value)
        return False

    start = next((i for i, row in enumerate(parsed) if nonempty(row)), 0)
    header_start = start
    header_depth = 1

    # Recognize a two-level header followed by a separate index-name row.
    for i in range(start, max(start, len(parsed) - 2)):
        top, sub, index_row = parsed[i], parsed[i + 1], parsed[i + 2]
        if (
            len(nonempty(top)) >= 2
            and repeated_nonempty(top)
            and len(nonempty(sub)) >= 2
            and sum(bool(v.strip()) for v in index_row) == 1
            and index_row[0].strip()
        ):
            header_start = i
            header_depth = 3
            break

    if header_depth == 1:
        # Skip leading preamble rows when a textual header is followed by tabular data.
        for i in range(start, len(parsed) - 1):
            current = parsed[i]
            following = parsed[i + 1]
            current_values = nonempty(current)
            following_values = nonempty(following)
            if len(current_values) < 2 or not following_values:
                continue
            numeric_share = sum(is_number(v) for v in following_values) / len(following_values)
            textual_share = sum(not is_number(v) for v in current_values) / len(current_values)
            if numeric_share >= 0.5 and textual_share >= 0.5:
                header_start = i
                break

    if header_depth == 3:
        top, sub, index_row = parsed[header_start:header_start + 3]
        width = max(len(top), len(sub), len(index_row))
        columns = []
        for col in range(width):
            if col == 0:
                label = index_row[col].strip() if col < len(index_row) else ""
            else:
                parts = []
                for source in (top, sub):
                    if col < len(source) and source[col].strip():
                        parts.append(source[col].strip())
                label = "_".join(parts)
            columns.append(label)
        data_start = header_start + 3
    else:
        header = parsed[header_start]
        columns = [value.strip() for value in header]
        data_start = header_start + 1

    records = parsed[data_start:]
    width = max([len(columns)] + [len(row) for row in records]) if records else len(columns)

    while len(columns) < width:
        columns.append("")
    for i, name in enumerate(columns):
        if not name:
            columns[i] = "column_" + str(i + 1)

    normalized_rows = []
    for row in records:
        normalized_rows.append(row + [""] * (width - len(row)))

    return {"columns": columns, "rows": normalized_rows}
